from urban_micro import uhi
import itertools, json

def build_priority(specs, alpha=0.05):
    # specs: list of (pick_tuple, by, key, effect, q)
    hs = []
    eff = {}
    for i,(pick,by,key,effect,q) in enumerate(specs):
        hs.append('{"pick":%s,"by":"%s","key":"%s","steps":10,"hits":10,"max_abs":%d,"persistence":1.000000}'
                  % (json.dumps(list(pick)), by, key, i+1))
        eff[(pick,by,key)] = (effect,q)
    rank = '{"alpha":%.6f,"hotspots":[%s]}\n' % (alpha, ",".join(hs))
    return uhi.rank_hotspot_priority(rank, eff)

specs = [
 (("green","roof"), "region","R1", -1.0, 0.01),
 (("material",),    "region","R1", -2.0, 0.02),
]
priority = build_priority(specs)
print(priority)

