            raise ValueError(
                "allow values must be duplicate-free lists of that"
                " panel's pick tuples"
            ) from None
        if not belongs or duplicate:
            raise ValueError(
                "allow values must be duplicate-free lists of that"
                " panel's pick tuples"
            )
        members.add(pick)
    allowed[panel] = members

